 async function revealDisclosureByWheel(p,rec,disclosure,name){
  const events=[];const wheel=async delta=>{const before=await p.evaluate(()=>scrollY);await p.mouse.move(p.viewportSize().width-10,Math.min(500,p.viewportSize().height-30));await p.mouse.wheel(0,delta);await rest(p);events.push({delta,before,after:await p.evaluate(()=>scrollY)});};
  await wheel(250);
  for(let n=0;n<12;n++){const g=await disclosure.evaluate(e=>({rect:e.getBoundingClientRect().toJSON(),header:document.querySelector('header')?.getBoundingClientRect().bottom??0,height:innerHeight}));if(g.rect.top>=g.header+8&&g.rect.bottom<=g.height-8)break;await wheel(g.rect.top<g.header+8?-100:100);}
  const pointer=await disclosure.evaluate(e=>{const r=e.getBoundingClientRect(),hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2),header=document.querySelector('header')?.getBoundingClientRect().bottom??0;return {rect:r.toJSON(),header,height:innerHeight,centerHitsTarget:!!hit&&e.contains(hit)};});rec.info(`${name}: actual native wheel events and scroll positions`,JSON.stringify(events));rec.check(`${name}: ordinary pointer target fully exposed and hit-testable`,pointer.rect.width>=24&&pointer.rect.height>=24&&pointer.rect.top>=pointer.header&&pointer.rect.bottom<=pointer.height&&pointer.centerHitsTarget,JSON.stringify({...pointer,wheelEvents:events.length}));
 }
