 // The sole mocked API: actual navigator.clipboard.writeText, always rejects. Deferred variants only reject;
 // no fake successful writes. UI/worker data and request routes remain real. Restore in finally.
 async function rejectWrites(p,{deferred=false}={}){await p.evaluate(({deferred})=>{if(window.__3FCopy)throw Error('Nested clipboard injection');const target=navigator.clipboard,own=Object.getOwnPropertyDescriptor(target,'writeText'),original=target.writeText;const state={own,original,calls:[],pending:[]};window.__3FCopy=state;Object.defineProperty(target,'writeText',{configurable:true,value(text){state.calls.push(text);if(deferred)return new Promise((_,reject)=>state.pending.push(()=>reject(new DOMException('3.F deliberate real API rejection','NotAllowedError'))));return Promise.reject(new DOMException('3.F deliberate real API rejection','NotAllowedError'));}});},{deferred});}
 async function restoreWrites(p){await p.evaluate(()=>{const s=window.__3FCopy;if(!s)return;for(const reject of s.pending.splice(0))reject();if(s.own)Object.defineProperty(navigator.clipboard,'writeText',s.own);else delete navigator.clipboard.writeText;delete window.__3FCopy;});}
 const calls=p=>p.evaluate(()=>window.__3FCopy.calls.slice());
 async function rejectPending(p,index){await p.evaluate(index=>{const fn=window.__3FCopy.pending[index];if(typeof fn!=='function')throw Error(`No pending copy ${index}`);window.__3FCopy.pending[index]=()=>{};fn();},index);await rest(p);}
