 async function dialogs(ctx,rec,lds,shared){for(const k of ENTITY_KINDS){const p=k==='drills'?shared:lds;await ui.viewToggle(p,'Configure').click();await ui.diagramView(p).click();await ui.oneEditorNodes(p).first().waitFor();const ns=ui.oneEditorNodes(p);let id=null;for(let n=0;n<await ns.count();n++)if((await ns.nth(n).innerText()).split('\n')[0].trim()===`${singular[k]} 1`)id=await ns.nth(n).getAttribute('data-id');if(!id)throw Error(`Missing ${singular[k]}1 actual Diagram node`);const node=ui.oneEditorNode(p,id);await reach(p,rec,node,`${singular[k]}1 Diagram node`);await node.press('Enter');await ui.oneEditorDialog(p).waitFor();const d=ui.oneEditorDialog(p);await restDialog(p,d);await shot(p,rec,`${k}-entity-draft`,{short:true,scope:d});for(const [text,loc]of [['Save',ui.oneEditorSave(p)],['Cancel',ui.oneEditorCancel(p)]]){await reach(p,rec,loc,text);await appearance(p,rec,loc,text);}await mouse(p,rec,ui.oneEditorCancel(p),'Cancel entity draft');await d.waitFor({state:'hidden'});await rest(p);await ui.listView(p).click();}
 }
