 async function copyWarningsAndRunning(ctx,rec){
  const below=await fresh(ctx,rec,BELOW_TARGET_SAMPLE);try{await generateOnce(below,rec,'below-target actual fixture');const snapshot=await stringOf(below);rec.check('actual below-target Copy is explicitly labelled',/below target/i.test(await ui.followHeaderCopy(below).getAttribute('aria-label')??await ui.followHeaderCopy(below).innerText()));await rejectWrites(below);try{await ui.followHeaderCopy(below).click();await failure(below,rec,snapshot,'copy-rejected-below-target',{warning:true});}finally{await restoreWrites(below);}}finally{await below.context().close();}
  const pin=await fresh(ctx,rec,sample('science/automation-science/automation-science-belted-buffer.json'));try{await checkOnly(pin,rec,'current-best real fixture');await rejectWrites(pin);try{await ui.generate(pin).click();await pin.waitForFunction(()=>[...document.querySelectorAll('header button')].some(b=>b.textContent?.trim().startsWith('Copy current best')),null,{timeout:10000});rec.check('real current-best button sampled while generation runs',await ui.cancel(pin).count()===1);const attempted=await stringOf(pin);await ui.followHeaderCopy(pin).click();await failure(pin,rec,attempted,'copy-current-best-rejected');await complete(pin,rec,'current-best rejected run');const selected=await ui.clockRows(pin).evaluateAll(es=>es.filter(e=>e.classList.contains('Mui-selected')).map(e=>e.textContent));rec.check('rejected current-best/manual-selection never pins over final recommendation',selected.length===1&&/Recommended/.test(selected[0]),JSON.stringify(selected));await shot(pin,rec,'copy-rejected-best-finished-unpinned');}finally{await restoreWrites(pin);}}finally{await pin.context().close();}
 }
 const run=await forWidths(WIDTHS,async ctx=>{const {rec}=ctx;
  rec.info('source provenance','Root must record immutable UI+engine tree/build SHA/preview identity and actual commands. Writer source is not browser evidence. Baseline prior to layout edits is separate.');
  rec.info('scope','Seven explicit corrections plus inherited B controls; D1–D8, engine/sidecar/dependencies/settings remain outside this capture. No fake data or persistence writes.');
  await shot(ctx.page,rec,'initial-blank-main-actions');
  const smallInput=config(SMALL_SAMPLE);smallInput.target_output={...smallInput.target_output,copies:0.5,items_per_second:10};smallInput.inserters=smallInput.inserters.map((x,i)=>({...x,prototype:'stack-inserter',quality:'legendary',source:x.source.type==='belt'?{...x.source,near_lane:2}:x.source,overrides:{...x.overrides,enable_control:{mode:'AUTO'}}}));writeFileSync(join(OUT,'test-inputs','small-preservation-input.json'),JSON.stringify(smallInput,null,2));
  rec.info('derived SMALL input','Real original SMALL physical build with fractional Copies0.5/rate10, explicit existing stack-inserter/legendary metadata, belt near_lane2 and explicit AUTO rule; imported through actual UI, generated by real worker. It is a UI test fixture, not an in-game export.');
  const p=await fresh(ctx,rec,STEPS.has('paste')?smallInput:SMALL_SAMPLE),lds=await fresh(ctx,rec,LDS),shared=await fresh(ctx,rec,SHARED);try{
   if(STEPS.has('help'))await step(ctx,rec,'Advanced click/tap and persistent input descriptions',()=>help(ctx,rec,p));
   if(STEPS.has('stale'))await step(ctx,rec,'readable stale plan and checking inertness',()=>stale(ctx,rec,p));
   if([...STEPS].some(x=>['copy','paste','reflow'].includes(x)))await step(ctx,rec,'one shared SMALL real generation',()=>generateOnce(p,rec,'shared SMALL'));
   if(STEPS.has('output')){await step(ctx,rec,'real iron bacteria machine aggregate/per-inserter evidence',()=>output(ctx,rec));if([...STEPS].some(x=>['copy','paste','reflow'].includes(x)))await step(ctx,rec,'comparison Output swings help consistency',()=>expandedSwingsHelp(p,rec));}
   if(STEPS.has('fuel'))await step(ctx,rec,'real Fuel event parity and trace equivalents',()=>fuel(ctx,rec));
   if(STEPS.has('bulk'))await step(ctx,rec,'inherited B sticky/selection/filter/rule/Undo',()=>bulk(ctx,rec,lds));
   if(STEPS.has('dialogs'))await step(ctx,rec,'all-five real entity draft dialogs',()=>dialogs(ctx,rec,lds,shared));
   if(STEPS.has('paste'))await step(ctx,rec,'selective Paste counts/crossings/ack/reset/Cancel/Undo',()=>paste(ctx,rec,p,lds,shared));
   if(STEPS.has('reflow'))await step(ctx,rec,'ordinary UI/error/header/library/Paste/Results reflow',()=>reflow(ctx,rec,p,lds,shared));
   // Copy ends by creating a real replacement build, so it follows all reuse of this completed SMALL run.
   if(STEPS.has('copy')){await step(ctx,rec,'actual native success and rejected Copy snapshot/races',()=>withClipboard(()=>copy(ctx,rec,p)));await step(ctx,rec,'below-target and current-best rejected Copy',()=>copyWarningsAndRunning(ctx,rec));}
  }finally{await Promise.all([p.context().close(),lds.context().close(),shared.context().close()]);}
 },{out:OUT,base:BASE});
 process.exitCode=run.finish({title:'3.F safety/accessibility follow-ups — real UI evidence'});
